const Sidebar: NextPage = () => {
  const pathname = usePathname();

  return (
    <div className='min-w-[250px] min-h-screen shrink-0 bg-white shadow-sidebar flex flex-col gap-16 py-10 pl-8 fixed'>
      <Logo fill='currentColor' />

      <div className='flex-grow flex flex-col gap-12'>
        {sidebarItems.map((item, index) => (
          <Link
            href={item.href}
            key={index}
            className={`flex items-center gap-4 self-stretch py-2 transition-all duration-500 ${
              pathname.includes(item.href)
                ? 'text-primary-purple-60 border-r-8 border-primary-purple-60 font-semibold'
                : 'text-gray-900'
            }`}
          >
            {item.icon}
            <p className={`text-xl ${pathname === item.href ? 'text-primary-purple-60' : 'text-gray-900'}`}>
              {item.title}
            </p>
          </Link>
        ))}
      </div>

      <div className='flex flex-col gap-8'>
        {sidebarOthers.map((item, index) => (
          <Link
            href={item.href}
            key={index}
            className={`flex items-center gap-4 self-stretch py-2 transition-all duration-500 ${
              pathname === item.href
                ? 'text-primary-purple-60 border-r-8 border-primary-purple-60'
                : item.title === 'Sign out'
                ? 'text-error-error'
                : 'text-gray-900'
            }`}
          >
            {item.icon}
            <p
              className={`text-xl ${
                pathname === item.href && pathname !== '/dashboard/sign-out'
                  ? 'text-primary-purple-60 font-semibold'
                  : item.title === 'Sign out'
                  ? 'text-error-error'
                  : 'text-gray-900'
              }`}
            >
              {item.title}
            </p>
          </Link>
        ))}
      </div>
    </div>
  );
};

export default Sidebar;
